def test_csharp_cpp_named_entities_agree_in_diff_and_index(source, path, expected):
    from hashlib import blake2b

    from gita.index.evidence import parse_evidence

    tree = extract(source, path)
    assert not tree.parse_error
    bundle = parse_evidence(source, path.encode("ascii"))
    assert bundle.result.complete
    definitions = [definition for definition in bundle.result.definitions if not definition.synthetic_root]
    assert {definition.names: definition.kind for definition in definitions} == expected
    assert len(definitions) == len(expected) + 1, "overloads must remain separate definitions"
    assert len({definition.id for definition in definitions}) == len(definitions)
    versions = {version.id: version for version in bundle.versions}
    for definition in definitions:
        version = versions[definition.version_id]
        span = definition.span
        assert version.source_digest == blake2b(source[span.start_byte:span.end_byte], digest_size=32).digest()
        matching = [entity for entity in tree.walk() if not entity.synthetic
                    and entity.name == definition.names[-1] and entity.start_line == span.start_line]
        assert len(matching) == 1
        assert matching[0].kind.value == definition.kind
        if definition.parent_id is not None:
            parent = next(parent for parent in bundle.result.definitions if parent.id == definition.parent_id)
            assert parent.span.start_byte <= span.start_byte <= span.end_byte <= parent.span.end_byte


@pytest.mark.parametrize("source,path,old,new,name,kind", (
    (CSHARP, "Store.cs", b"return key + 1", b"return key + 2", "Read", ChangeKind.BODY_CHANGED),
    (CSHARP, "Store.cs", b"Value => 42", b"Value => 43", "Value", ChangeKind.BODY_CHANGED),
    (CPP, "store.hpp", b"return key + 1", b"return key + 2", "get", ChangeKind.BODY_CHANGED),
    (CPP, "store.hpp", b"template<typename T>", b"template<typename T, typename U>", "read", ChangeKind.SIGNATURE_CHANGED),
))
def test_csharp_cpp_changes_are_attributed_to_named_members(source, path, old, new, name, kind):
    from gita.index.evidence import parse_evidence

    changed = source.replace(old, new)
    changes = diff_trees(extract(source, path), extract(changed, path))
    assert any(change.entity.name == name and change.kind is kind for change in changes)
    before, after = [parse_evidence(data, path.encode("ascii")) for data in (source, changed)]
    assert before.result.complete and after.result.complete
    versions = []
    for bundle in (before, after):
        needle = old if bundle is before else new
        definition = next(item for item in bundle.result.definitions if item.names[-1] == name
                  and needle in (source if bundle is before else changed)[item.span.start_byte:item.span.end_byte])
        versions.append(next(version for version in bundle.versions if version.id == definition.version_id))
    if kind is ChangeKind.BODY_CHANGED:
        assert versions[0].signature == versions[1].signature
        assert versions[0].body != versions[1].body
    else:
        assert versions[0].signature != versions[1].signature
        assert versions[0].body == versions[1].body


